function describe() {
  return `${this.name}:${this.size}`;
}

const box = { name: "box", size: 2, describe };
const crate = { name: "crate", size: 9, describe, inner: box };

console.log(crate.inner.describe());

const alias = crate;
alias.name = "big";

console.log(crate.describe());

crate.inner = { name: "bag", describe: box.describe };

console.log(crate.inner.describe());
console.log(box.describe());
